    "ingress": [
      {
        "from": [
          {
            "podSelector": {
              "matchLabels": {
                "role": "trusted"
              }
            },
            {
              "namespaceSelector": {
                "matchLabels": {
                  "team": "clients"
                }
              }
            }
          ],
          "ports": [
            {
              "port": 80,
              "protocol": "TCP"
            }
          ]
        }
      ]
    }
  }
}
